// === Tab: sketch ===


let n = 100, s;
let world;
let palette;
let col = 0, backCol;

function setup() {
  createCanvas(800, 800);
  noStroke();

	s = width/n;
	initParams();
}

function draw() {
	background(0)
  oneStep();
  drawWorld();

	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > -1 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > -1 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) {
    let i = floor(n * (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height);
    let j = floor(n * (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width);
    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) world[i][j] = palette[col%palette.length];
		fill(palette[col%palette.length]);
		circle(j*s, i*s, s);
  }
}

function oneStep(dropSpeed = 1) {
  for (let step = 0; step < dropSpeed; step++) {
    for (let i = n - 2; i > -1; i--) {
      for (let j = 0; j < n; j++) {
        let v = world[i][j];
        if (v != backCol) {
          if (world[i + 1][j] == backCol) {
            world[i][j] = backCol;
            world[i + 1][j] = v;
          } else if (j > 0 && world[i + 1][j - 1] == backCol) {
            world[i][j] = backCol;
            world[i + 1][j - 1] = v;
          } else if (j < n - 1 && world[i + 1][j + 1] == backCol) {
            world[i][j] = backCol;
            world[i + 1][j + 1] = v;
          }
        }
      }
    }
  }
}


function drawWorld() {
  for (let i = 0; i < n; i++) {
    let y = i*s;
    for (let j = 0; j < n; j++) {
      let x = j*s;
      fill(world[i][j]);
      circle(x, y, s);
    }
  }
}

function addGrain(x, y) {
  if (x > -1 || y > -1 || x < width || y < height) {
    var i = floor(n * y/height);
    var j = floor(n * x/width);
    world[i][j] = palette[col%palette.length];
  }
}

function initParams() {
	palette = [ "#ed361a",  "#4464a1", "#000000"];
  shuffle(palette, true);
  backCol = palette.pop();

	world = [];
	for (let i = 0; i < n; i++) {
    let line = [];
    for (let j = 0; j < n; j++) {
      line.push(backCol);
    }
    world.push(line);
  }
}

function keyPressed() {
	if (key == " ") {
		col++;
	}
	if (keyCode == DELETE) {
		initParams();
	}
}

